@using sv_92eae7ad15214e93a5f6a125673f88a4.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var cssClass = GetStepClass(step);
        <div class="step @cssClass" @onclick="() => OnStepClick(step)">
