@page "/apply"
@using sv_92eae7ad15214e93a5f6a125673f88a4.Models
@using sv_92eae7ad15214e93a5f6a125673f88a4.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnNavigateToStep="NavigateToStep" />

    <div class="row justify-content-center">
        <div class="col-lg-8">
            @switch (currentStep)
            {
                case 0:
                    <PersonalInfoStep Model="formState.Personal"
                                      ValidateEmail="ApplicationService.ValidateEmailAsync"
                                      OnNext="NextStep" />
                    break;
                case 1:
                    <WorkHistoryStep Entries="formState.WorkEntries"
                                     OnNext="NextStep"
                                     OnBack="PreviousStep" />
                    break;
                case 2:
                    <ReferencesStep References="formState.References"
                                    OnNext="NextStep"
                                    OnBack="PreviousStep" />
                    break;
                case 3:
                    <CoverLetterStep CoverLetter="@formState.CoverLetter"
                                     CoverLetterChanged="UpdateCoverLetter"
                                     OnNext="NextStep"
                                     OnBack="PreviousStep" />
                    break;
                case 4:
                    <ReviewStep FormState="formState"
                                IsSubmitted="isSubmitted"
                                ApplicationId="applicationId"
                                OnBack="PreviousStep"
                                OnEditStep="NavigateToStep"
                                OnSubmit="SubmitApplication" />
                    break;
            }
        </div>
    </div>
</div>

@code {
    private ApplicationFormState formState = new();
    private int currentStep;
    private bool isSubmitted;
    private int? applicationId;

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void NavigateToStep(int step) => currentStep = step;

    private void UpdateCoverLetter(string value)
    {
        formState.CoverLetter = value;
    }

    private async Task SubmitApplication()
    {
        var application = formState.ToRecord();
        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitted = true;
    }
}

